-- 2. Fiches des classes
-- Rôdeur bédouin
SET @xc_cla_126 := (SELECT MIN(cla_id) FROM dd_classes WHERE cla_nom = 'Rôdeur bédouin' AND cla_ruleset_var_id = 1 AND cla_camp_id IS NULL AND IFNULL(cla_cla_id, 0) = 0);
SET @xc_cla_126 := (SELECT MIN(cla_id) FROM dd_classes WHERE cla_nom = 'Rôdeur bédouin' AND cla_ruleset_var_id = 1 AND cla_camp_id IS NULL AND IFNULL(cla_cla_id, 0) = 0);
UPDATE dd_classes SET cla_nom = 'Rôdeur bédouin', cla_abreviation = 'R', cla_clt_id = 1, cla_dV = 8, cla_alignement = '', cla_car_id = 0, cla_mag_id = 0, cla_profil_incantation = 0, cla_renouvellement = 0, cla_sort_connu = 1, cla_sort_compris = 1, cla_sort_prepare = 1, cla_domaine_divin = 0, cla_niveauMax = 20, cla_pointsCompetences = 6, cla_po_niveau1 = 0, cla_conditions = '', cla_armes = '', cla_armures = NULL, cla_outils = NULL, cla_sauvegardes = NULL, cla_equipement = NULL, cla_competences = '', cla_sorts = '', cla_description = '<p>Pour ceux qui aiment le frisson de la chasse, seules comptent les notions de pr&eacute;dateurs et de proies. Qu&rsquo;ils soient &eacute;claireurs, pisteurs ou chasseurs de prime, les r&ocirc;deurs partagent de nombreuses particularit&eacute;s : une ma&icirc;trise in&eacute;gal&eacute;e de certaines armes, une grande habilet&eacute; pour d&eacute;busquer le gibier, m&ecirc;me le plus inaccessible, et un savoir-faire leur permettant de venir &agrave; bout d&rsquo;une grande vari&eacute;t&eacute;s de proies. Ces chasseurs allient savoir, patience et habilet&eacute; pour traquer les hommes, les b&ecirc;tes ou encore les animaux. Ils d&eacute;veloppent un instinct de pr&eacute;dateur, un savoir-faire applicable &agrave; de multiples environnements et des capacit&eacute;s martiales toujours plus dangereuses. Certains chassent les cr&eacute;atures qui s&rsquo;attaquent aux humains et prot&egrave;gent les fronti&egrave;res de la civilisation alors que d&rsquo;autres se lancent &agrave; la poursuite d&rsquo;un gibier plus rus&eacute;, et parfois m&ecirc;me de fugitifs appartenant &agrave; la m&ecirc;me communaut&eacute; qu&rsquo;eux.</p>', cla_regles_speciales = '<h1>Le Chant des Puits</h1>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\"><strong>Voie de la survie personnelle. </strong>Les B&eacute;douins ne dessinent pas de cartes : ils les chantent. Chaque strophe du Chant des Puits porte un savoir que la tribu s&rsquo;est transmis depuis des g&eacute;n&eacute;rations, sur l&rsquo;eau, les pistes, les b&ecirc;tes et les vents. Celui qui l&rsquo;a appris traverse le d&eacute;sert l&agrave; o&ugrave; les &eacute;trangers meurent.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">1. Sens de l&rsquo;eau</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau1)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Apr&egrave;s dix minutes pass&eacute;es &agrave; &eacute;couter le sable et le vent, le r&ocirc;deur fait un test de Survie (DD 15 ; DD 20 dans le d&eacute;sert profond). En cas de r&eacute;ussite, il conna&icirc;t la direction et la distance approximative du point d&rsquo;eau le plus proche (guelta, puits, nappe affleurante, citerne cach&eacute;e) dans un rayon de 500 m par niveau de personnage.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Il peut l&rsquo;utiliser une fois par heure. Il ne d&eacute;tecte pas la qualit&eacute; de l&rsquo;eau : une mare empoisonn&eacute;e reste une mare.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">2. Corps du d&eacute;sert</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 1)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le r&ocirc;deur est fait pour la Lame. Il b&eacute;n&eacute;ficie d&rsquo;un niveau suppl&eacute;mentaire de protection contre la chaleur, cumulatif avec &laquo; Natif du d&eacute;sert &raquo; (voir l&rsquo;annexe 1 du sc&eacute;nario), et gagne un bonus de +4 aux jets de Vigueur contre la soif, la famine et les effets de la chaleur. Il ne consomme que la moiti&eacute; de l&rsquo;eau dont un personnage a normalement besoin.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">3. Pas du sable</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 3)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">En armure l&eacute;g&egrave;re ou interm&eacute;diaire et sans charge lourde, la vitesse de d&eacute;placement du r&ocirc;deur augmente de 3 m. Le sable meuble, les dunes et les terrains ensabl&eacute;s ne le ralentissent jamais.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">4. Langage des b&ecirc;tes</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 5)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le r&ocirc;deur communique des notions simples (danger, eau, nourriture, direction, &laquo; ami &raquo; ou &laquo; ennemi &raquo;) avec les animaux du d&eacute;sert : chameaux, faucons, gazelles, scorpions, serpents. Il utilise sa comp&eacute;tence Dressage &agrave; la place de Diplomatie pour modifier leur attitude.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Il ne contr&ocirc;le pas ces animaux, et ils ne lui r&eacute;pondent que dans la limite de leur intelligence.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">5. Lire le vent</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 5)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le r&ocirc;deur pr&eacute;voit les temp&ecirc;tes de sable, les orages et les changements de temps avec 24 heures d&rsquo;avance, et gagne un bonus de +4 aux tests de Survie pour s&rsquo;orienter. Il ignore les malus que le vent inflige aux jets d&rsquo;attaque &agrave; distance et aux tests de D&eacute;tection et de Perception auditive, jusqu&rsquo;au vent violent compris (tels que d&eacute;finis dans le Guide du Ma&icirc;tre).</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">6. Cataplasmes du d&eacute;sert</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 7)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Avec des r&eacute;sines, des herbes et de l&rsquo;eau, le r&ocirc;deur pr&eacute;pare un cataplasme. En une action complexe, il soigne une cr&eacute;ature vivante (lui-m&ecirc;me compris) de 1d8 points de vie + son niveau de personnage (maximum +5). Il peut le faire un nombre de fois par jour &eacute;gal &agrave; son modificateur de Sagesse (minimum 1).</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">C&rsquo;est l&rsquo;art des gu&eacute;risseuses des tentes, la seule &laquo; faveur des dieux &raquo; que les B&eacute;douins tol&egrave;rent, et la preuve que l&rsquo;on soigne sans toucher &agrave; la magie.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">7. Fils du sable</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 13)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">En terrain d&eacute;sertique, le r&ocirc;deur ne laisse aucune trace, sauf s&rsquo;il le souhaite, et il peut utiliser Discr&eacute;tion m&ecirc;me quand il est observ&eacute; et en l&rsquo;absence de couvert ou de camouflage. Il peut aussi s&rsquo;enterrer dans le sable (action complexe) pour tendre une embuscade : une cr&eacute;ature qui passe &agrave; moins de 3 m doit r&eacute;ussir un test de D&eacute;tection (DD 20 + modificateur de Sagesse du r&ocirc;deur) pour le remarquer, sinon il b&eacute;n&eacute;ficie d&rsquo;un round de surprise.</p>\r\n<h1>La Voie du Rafiq</h1>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\"><strong>Voie du garant du groupe. </strong>Un rafiq est un membre de la tribu qui voyage avec des &eacute;trangers et r&eacute;pond d&rsquo;eux : frapper des voyageurs accompagn&eacute;s d&rsquo;un rafiq, c&rsquo;est frapper sa tribu. Cette voie rassemble ce qu&rsquo;il faut pour mener un groupe entier &agrave; travers le d&eacute;sert, et le faire accueillir l&agrave; o&ugrave; l&rsquo;on n&rsquo;accueille personne.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">1. Guide du d&eacute;sert</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 1)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Quand le r&ocirc;deur m&egrave;ne le groupe, les alli&eacute;s qui le suivent profitent de son r&eacute;sultat de Survie pour ne pas se perdre. Ils gagnent aussi un bonus de +2 aux jets de Vigueur contre la chaleur, la soif et la marche forc&eacute;e tant qu&rsquo;ils restent &agrave; moins de 18 m de lui.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">2. Pain, sel et eau</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 1)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le r&ocirc;deur gagne un bonus de +2 aux tests de Diplomatie et de Renseignements aupr&egrave;s des gens du d&eacute;sert.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\"><strong>Hospitalit&eacute;. </strong>Quand le groupe a partag&eacute; le pain, le sel et l&rsquo;eau avec un h&ocirc;te b&eacute;douin, la coutume de l&rsquo;hospitalit&eacute; s&rsquo;applique : pendant trois jours, cet h&ocirc;te et les siens ne leur feront aucun mal, sauf si l&rsquo;un d&rsquo;eux viole l&rsquo;hospitalit&eacute; en premier. Le MJ module la dur&eacute;e selon l&rsquo;h&ocirc;te.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\"><strong>Faveur. </strong>Une fois par semaine et par tribu alli&eacute;e, le r&ocirc;deur peut demander une faveur raisonnable : un guide, un abri, des montures, de l&rsquo;eau, des informations. Jamais de combattre &agrave; sa place.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">3. Khreima</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 5)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">En 10 minutes et un test de Survie (DD 15), le r&ocirc;deur monte un campement de fortune qui abrite jusqu&rsquo;&agrave; six cr&eacute;atures. Celles qui s&rsquo;y reposent pendant 8 heures b&eacute;n&eacute;ficient de soins de longue dur&eacute;e sans test de Premiers secours : elles r&eacute;cup&egrave;rent leurs points de vie et leurs points de caract&eacute;ristique au double de la vitesse normale. Cela ne se cumule pas avec les soins de longue dur&eacute;e d&rsquo;un autre personnage.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Les soins de longue dur&eacute;e sont aussi ceux qui soignent la d&eacute;shydratation dans la zone de magie morte (annexe 1 du sc&eacute;nario).</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">4. Veille du rafiq</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 5)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le r&ocirc;deur dort d&rsquo;un sommeil l&eacute;ger : il garde ses tests de Perception auditive et de D&eacute;tection normaux pendant son sommeil et se r&eacute;veille au moindre bruit anormal. Tant qu&rsquo;il n&rsquo;est pas surpris, les alli&eacute;s &agrave; 9 m ou moins ne le sont pas non plus, et ils gagnent +2 aux jets d&rsquo;initiative.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">5. Marche de caravane</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 7)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Le groupe qui voyage avec le r&ocirc;deur, montures comprises, peut marcher 10 heures par jour au lieu de 8 sans test de marche forc&eacute;e. Les tests de marche forc&eacute;e ne commencent qu&rsquo;apr&egrave;s la dixi&egrave;me heure.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">6. Appel de la tribu</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 13)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Une fois par semaine, le r&ocirc;deur lance un signal (fum&eacute;e, miroir, vol de son compagnon animal). Si un camp de sa tribu ou d&rsquo;une tribu alli&eacute;e se trouve &agrave; deux jours de marche ou moins, 2d4 guerriers b&eacute;douins de niveau 1 &agrave; 3 arrivent en 1d6 heures. Ils r&eacute;pondent &agrave; ses demandes raisonnables pendant 24 heures, apr&egrave;s quoi ils repartent ; le MJ les contr&ocirc;le.</p>\r\n<div style=\"mso-element: para-border-div; border: none; border-bottom: solid #C9B48A 1.0pt; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm 0cm 2.0pt 0cm;\">\r\n<p class=\"MsoNormal\" style=\"page-break-after: avoid; tab-stops: right 481.9pt; border: none; mso-border-bottom-alt: solid #C9B48A .75pt; padding: 0cm; mso-padding-alt: 0cm 0cm 2.0pt 0cm; margin: 10.0pt 0cm 2.0pt 0cm;\"><strong><span style=\"font-size: 12.0pt; color: #5a2e12;\">7. Garant jusqu&rsquo;au bout</span></strong><em><span style=\"font-size: 10.0pt; color: #7a3e1a;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span>(Niveau 17)</span></em></p>\r\n</div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Une fois par jour, en action imm&eacute;diate, le r&ocirc;deur d&eacute;signe un alli&eacute; situ&eacute; &agrave; 9 m ou moins qui devrait mourir (points de vie &agrave; &minus;10 ou moins) : les points de vie de l&rsquo;alli&eacute; sont ramen&eacute;s &agrave; 1. Le r&ocirc;deur est alors fatigu&eacute; jusqu&rsquo;&agrave; ce qu&rsquo;il se soit repos&eacute; 8 heures, ou &eacute;puis&eacute; s&rsquo;il l&rsquo;&eacute;tait d&eacute;j&agrave;.</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 5.0pt; line-height: 115%;\">Un rafiq qui laisse mourir ceux dont il r&eacute;pond perd son honneur ; celui-ci pr&eacute;f&egrave;re payer de sa personne.</p>', cla_traits = NULL, cla_caracteristiques = NULL, cla_critere_rec = 'so_rodeur', cla_pouvoir1 = '', cla_pouvoir2 = '', cla_pouvoir3 = '', cla_pouvoir4 = '', cla_pouvoir5 = '', cla_public = 0, cla_visible = 1, cla_ruleset_var_id = 1, cla_res_id = @xc_res_99, cla_cla_id = NULL, cla_camp_id = NULL WHERE cla_id = @xc_cla_126;

-- 3. Données liées
-- Rôdeur bédouin
DELETE FROM dd_classe_niveau WHERE cn_cla_id = @xc_cla_126;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1243 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Empathie sauvage');
SET @xc_cap_1243 := IFNULL(@xc_cap_1243, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Empathie sauvage' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = '<p>Un r&ocirc;deur peut ajuster son comportement, son langage et ses expressions corporelles pour améliorer l\'attitude d\'un animal (comme un ours ou un varan). Cette aptitude suit les m&ecirc;mes règles que les tests de Diplomatie joués pour modifier l\'attitude d\'une personne. Le résultat d\'un test d\'empathie sauvage est déterminé par 1d20 + le niveau du r&ocirc;deur + le modificateur de Charisme du r&ocirc;deur. L\'attitude initiale des animaux domestiques est l\'indifférence, tandis que les animaux sauvages sont généralement inamicaux.</p>\n\n<p>Pour utiliser d\'empathie sauvage, le r&ocirc;deur et l\'animal doivent &ecirc;tre en mesure de se voir et de l\'étudier l\'un l\'autre, ce qui signifie qu\'ils doivent se trouver à moins de 9 mètres de distance dans des conditions normales. Il faut en moyenne une minute pour influencer un animal de cette fa&ccedil;on, mais comme pour la diplomatie, cela peut parfois prendre plus longtemps ou &ecirc;tre plus rapide.</p>\n\n<p>Cette aptitude peut aussi servir à un r&ocirc;deur pour influencer une créature magique dont la valeur d\'Intelligence est de 1 ou 2 (comme un basilic ou un girallon), avec cependant un malus de -4 sur son test.</p>\n'));
SET @xc_cap_1243 := IFNULL(@xc_cap_1243, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Empathie sauvage' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1243 := IFNULL(@xc_cap_1243, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Empathie sauvage', cap_description = '<p>Un r&ocirc;deur peut ajuster son comportement, son langage et ses expressions corporelles pour améliorer l\'attitude d\'un animal (comme un ours ou un varan). Cette aptitude suit les m&ecirc;mes règles que les tests de Diplomatie joués pour modifier l\'attitude d\'une personne. Le résultat d\'un test d\'empathie sauvage est déterminé par 1d20 + le niveau du r&ocirc;deur + le modificateur de Charisme du r&ocirc;deur. L\'attitude initiale des animaux domestiques est l\'indifférence, tandis que les animaux sauvages sont généralement inamicaux.</p>\n\n<p>Pour utiliser d\'empathie sauvage, le r&ocirc;deur et l\'animal doivent &ecirc;tre en mesure de se voir et de l\'étudier l\'un l\'autre, ce qui signifie qu\'ils doivent se trouver à moins de 9 mètres de distance dans des conditions normales. Il faut en moyenne une minute pour influencer un animal de cette fa&ccedil;on, mais comme pour la diplomatie, cela peut parfois prendre plus longtemps ou &ecirc;tre plus rapide.</p>\n\n<p>Cette aptitude peut aussi servir à un r&ocirc;deur pour influencer une créature magique dont la valeur d\'Intelligence est de 1 ou 2 (comme un basilic ou un girallon), avec cependant un malus de -4 sur son test.</p>\n', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1243;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1244 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Ennemis jurés');
SET @xc_cap_1244 := IFNULL(@xc_cap_1244, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Ennemis jurés' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = '<p>Au niveau 1, le r&ocirc;deur choisit un type de créatures de la Table : ennemis jurés du r&ocirc;deur. Pour avoir longuement étudié ses ennemis jurés et pour s\'&ecirc;tre exercé encore et encore aux techniques permettant de les vaincre, il bénéficie d\'un bonus de +2 aux tests de Bluff, Détection, Perception auditive, Psychologie et Survie lorsqu\'il les utilise contre des créatures de ce type. Il bénéficie également d\'un bonus de +2 sur les jets de dégêts d\'armes contre ces créatures.</p>\n\n<p>Au niveau 5 et tous les cinq niveaux par la suite (c\'est-à-dire aux niveaux 10, 15 et 20), le r&ocirc;deur peut choisir un nouvel ennemi juré sur la Table : ennemis jurés du r&ocirc;deur. De plus, il peut augmenter de +2 le bonus dont il bénéficie contre l\'un de ses ennemis jurés (y compris celui qu\'il vient de choisir s\'il le désire). Par exemple, un r&ocirc;deur de niveau 5 a deux ennemis jurés, un contre lequel il a un bonus de +4 sur les tests de Bluff, Détection, Perception auditive, Psychologie et Survie et les jets de dégêts d\'arme et un autre pour lequel le bonus n\'est que de +2. Au niveau 10, le m&ecirc;me r&ocirc;deur a trois ennemis jurés et il peut augmenter son bonus contre l\'un d\'eux de +2. Ses bonus seront alors soit de +4, +4 et +2, soit de +6, +2 et +2.</p>\n\n<p>Lorsqu\'un r&ocirc;deur choisit les Extérieurs ou les humano&iuml;des comme ennemi juré, il doit aussi choisir un sous-type associé, comme l\'indique la table. Si une créature appartient à deux sous-types d\'ennemi juré (par exemple, les démons sont à la fois du sous-type Chaos et Mal), les bonus ne se cumulent pas, le r&ocirc;deur ne profite que du plus élevé des deux. Voir livre de règles 1 pour plus de détails.</p>\n'));
SET @xc_cap_1244 := IFNULL(@xc_cap_1244, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Ennemis jurés' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1244 := IFNULL(@xc_cap_1244, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Ennemis jurés', cap_description = '<p>Au niveau 1, le r&ocirc;deur choisit un type de créatures de la Table : ennemis jurés du r&ocirc;deur. Pour avoir longuement étudié ses ennemis jurés et pour s\'&ecirc;tre exercé encore et encore aux techniques permettant de les vaincre, il bénéficie d\'un bonus de +2 aux tests de Bluff, Détection, Perception auditive, Psychologie et Survie lorsqu\'il les utilise contre des créatures de ce type. Il bénéficie également d\'un bonus de +2 sur les jets de dégêts d\'armes contre ces créatures.</p>\n\n<p>Au niveau 5 et tous les cinq niveaux par la suite (c\'est-à-dire aux niveaux 10, 15 et 20), le r&ocirc;deur peut choisir un nouvel ennemi juré sur la Table : ennemis jurés du r&ocirc;deur. De plus, il peut augmenter de +2 le bonus dont il bénéficie contre l\'un de ses ennemis jurés (y compris celui qu\'il vient de choisir s\'il le désire). Par exemple, un r&ocirc;deur de niveau 5 a deux ennemis jurés, un contre lequel il a un bonus de +4 sur les tests de Bluff, Détection, Perception auditive, Psychologie et Survie et les jets de dégêts d\'arme et un autre pour lequel le bonus n\'est que de +2. Au niveau 10, le m&ecirc;me r&ocirc;deur a trois ennemis jurés et il peut augmenter son bonus contre l\'un d\'eux de +2. Ses bonus seront alors soit de +4, +4 et +2, soit de +6, +2 et +2.</p>\n\n<p>Lorsqu\'un r&ocirc;deur choisit les Extérieurs ou les humano&iuml;des comme ennemi juré, il doit aussi choisir un sous-type associé, comme l\'indique la table. Si une créature appartient à deux sous-types d\'ennemi juré (par exemple, les démons sont à la fois du sous-type Chaos et Mal), les bonus ne se cumulent pas, le r&ocirc;deur ne profite que du plus élevé des deux. Voir livre de règles 1 pour plus de détails.</p>\n', cap_type = '', cap_choix_mode = 'texte', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1244;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1255 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Pistage');
SET @xc_cap_1255 := IFNULL(@xc_cap_1255, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Pistage' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = '<p>l faut r&eacute;ussir un test de Survie pour trouver des traces ou les suivre pendant 1,5 kilom&egrave;tre. Un nouveau test est n&eacute;cessaire lorsque la piste devient plus difficile &agrave; suivre, comme par exemple quand d\'autres traces la coupent ou quand elle se scinde en deux.</p>\n<p>Tant qu\'il piste, le personnage avance &agrave; la moiti&eacute; de sa vitesse de d&eacute;placement. Il peut avancer de sa vitesse de d&eacute;placement avec un malus aux tests de comp&eacute;tence de -5, ou au double de sa vitesse de d&eacute;placement avec un malus de -20 aux tests de comp&eacute;tence. Le DD d&eacute;pend du sol et des conditions en vigueur, selon la table suivante :</p>\n<p><code class=\"reg-tab-liste__tag\" title=\"Cliquer pour copier\">[[tab:pistage]]</code></p>\n<p><em>Sol tr&egrave;s mou</em>. Toute surface montrant des empreintes profondes et particuli&egrave;rement lisibles (neige, boue, &eacute;paisse couche de poussi&egrave;re, etc.).<br><em>Sol mou</em>. Toute surface assez &eacute;lastique pour s\'enfoncer sous le poids d\'un individu, mais plus r&eacute;sistante que la pr&eacute;c&eacute;dente. Les traces y sont nombreuses mais peu profondes.<br><em>Sol ferme</em>. La plupart des sols en ext&eacute;rieur (pelouse, champ, bois, etc.) et les surfaces molles ou extr&ecirc;mement sales &agrave; l\'int&eacute;rieur (&eacute;pais tapis, sol crasseux, etc.). La cr&eacute;ature suivie peut laisser quelques traces (brindilles cass&eacute;es, touffes de poils, etc.), mais les empreintes, elles, sont extr&ecirc;mement rares.<br><em>Sol dur</em>. Toute surface n\'imprimant pas la moindre empreinte (roche naturelle, plancher en pierre, etc.). La plupart des lits de cours d\'eau entrent dans cette cat&eacute;gorie, car les traces laiss&eacute;es sont g&eacute;n&eacute;ralement effac&eacute;es par le courant. La cr&eacute;ature suivie ne peut laisser que quelques indices de son passage (cailloux d&eacute;plac&eacute;s, marques de griffures, etc.).</p>\n<p>De nombreux modificateurs pouvant s\'appliquer au test de Survie sont pr&eacute;sentes ci-dessous :</p>\n<p>[[tab:classe-rodeur-pistage-modificateurs]]</p>\n<p><sup>1</sup> Si le groupe est compos&eacute; de cr&eacute;atures de tailles diverses, on prend seulement en compte la taille la plus importante.<br><sup>2</sup> Ces facteurs ne s\'additionnent pas ; seul le plus important est pris en compte.<br>Si le personnage rate son test de Survie, il peut r&eacute;essayer apr&egrave;s 1 heure (en ext&eacute;rieur) ou 10 minutes (&agrave; l\'int&eacute;rieur), moment qu\'il passe &agrave; essayer de retrouver la piste.</p>'));
SET @xc_cap_1255 := IFNULL(@xc_cap_1255, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Pistage' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1255 := IFNULL(@xc_cap_1255, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Pistage', cap_description = '<p>l faut r&eacute;ussir un test de Survie pour trouver des traces ou les suivre pendant 1,5 kilom&egrave;tre. Un nouveau test est n&eacute;cessaire lorsque la piste devient plus difficile &agrave; suivre, comme par exemple quand d\'autres traces la coupent ou quand elle se scinde en deux.</p>\n<p>Tant qu\'il piste, le personnage avance &agrave; la moiti&eacute; de sa vitesse de d&eacute;placement. Il peut avancer de sa vitesse de d&eacute;placement avec un malus aux tests de comp&eacute;tence de -5, ou au double de sa vitesse de d&eacute;placement avec un malus de -20 aux tests de comp&eacute;tence. Le DD d&eacute;pend du sol et des conditions en vigueur, selon la table suivante :</p>\n<p><code class=\"reg-tab-liste__tag\" title=\"Cliquer pour copier\">[[tab:pistage]]</code></p>\n<p><em>Sol tr&egrave;s mou</em>. Toute surface montrant des empreintes profondes et particuli&egrave;rement lisibles (neige, boue, &eacute;paisse couche de poussi&egrave;re, etc.).<br><em>Sol mou</em>. Toute surface assez &eacute;lastique pour s\'enfoncer sous le poids d\'un individu, mais plus r&eacute;sistante que la pr&eacute;c&eacute;dente. Les traces y sont nombreuses mais peu profondes.<br><em>Sol ferme</em>. La plupart des sols en ext&eacute;rieur (pelouse, champ, bois, etc.) et les surfaces molles ou extr&ecirc;mement sales &agrave; l\'int&eacute;rieur (&eacute;pais tapis, sol crasseux, etc.). La cr&eacute;ature suivie peut laisser quelques traces (brindilles cass&eacute;es, touffes de poils, etc.), mais les empreintes, elles, sont extr&ecirc;mement rares.<br><em>Sol dur</em>. Toute surface n\'imprimant pas la moindre empreinte (roche naturelle, plancher en pierre, etc.). La plupart des lits de cours d\'eau entrent dans cette cat&eacute;gorie, car les traces laiss&eacute;es sont g&eacute;n&eacute;ralement effac&eacute;es par le courant. La cr&eacute;ature suivie ne peut laisser que quelques indices de son passage (cailloux d&eacute;plac&eacute;s, marques de griffures, etc.).</p>\n<p>De nombreux modificateurs pouvant s\'appliquer au test de Survie sont pr&eacute;sentes ci-dessous :</p>\n<p>[[tab:classe-rodeur-pistage-modificateurs]]</p>\n<p><sup>1</sup> Si le groupe est compos&eacute; de cr&eacute;atures de tailles diverses, on prend seulement en compte la taille la plus importante.<br><sup>2</sup> Ces facteurs ne s\'additionnent pas ; seul le plus important est pris en compte.<br>Si le personnage rate son test de Survie, il peut r&eacute;essayer apr&egrave;s 1 heure (en ext&eacute;rieur) ou 10 minutes (&agrave; l\'int&eacute;rieur), moment qu\'il passe &agrave; essayer de retrouver la piste.</p>', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1255;
SET @xc_ci := NULL;
SET @xc_cap_1273 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Voie du désert');
SET @xc_cap_1273 := IFNULL(@xc_cap_1273, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Voie du désert' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = '<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Les rodeurs b&eacute;douins d&eacute;veloppenent des capacit&eacute;s sp&eacute;ciales en relation avec le d&eacute;sert.&nbsp; Tous les pouvoirs des voies du d&eacute;sert sont extraordinaires (Ex).&nbsp;<br></span></p>\n<p><!-- [if !supportLists]--><!--[endif]-->Au niveau 1, le&nbsp;r&ocirc;deur b&eacute;douin choisit sa voie de d&eacute;part : <em>Le Chant des Puits</em> ou <em>La Voie du Rafiq</em>. Il ne peut puiser que dans celle-l&agrave;. Au niveau 9, il ouvre la seconde voie. D&egrave;s lors, il choisit librement dans les deux.</p>\n<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Chaque capacit&eacute; sp&eacute;ciale indique un niveau de rodeur b&eacute;douin &agrave; partir duquel elle peut &ecirc;tre choisie.</span></p>'));
SET @xc_cap_1273 := IFNULL(@xc_cap_1273, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Voie du désert' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1273 := IFNULL(@xc_cap_1273, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Voie du désert', cap_description = '<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Les rodeurs b&eacute;douins d&eacute;veloppenent des capacit&eacute;s sp&eacute;ciales en relation avec le d&eacute;sert.&nbsp; Tous les pouvoirs des voies du d&eacute;sert sont extraordinaires (Ex).&nbsp;<br></span></p>\n<p><!-- [if !supportLists]--><!--[endif]-->Au niveau 1, le&nbsp;r&ocirc;deur b&eacute;douin choisit sa voie de d&eacute;part : <em>Le Chant des Puits</em> ou <em>La Voie du Rafiq</em>. Il ne peut puiser que dans celle-l&agrave;. Au niveau 9, il ouvre la seconde voie. D&egrave;s lors, il choisit librement dans les deux.</p>\n<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Chaque capacit&eacute; sp&eacute;ciale indique un niveau de rodeur b&eacute;douin &agrave; partir duquel elle peut &ecirc;tre choisie.</span></p>', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1273;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1245 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Style de combat');
SET @xc_cap_1245 := IFNULL(@xc_cap_1245, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Style de combat' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = ' Au niveau 2, un rôdeur doit choisir entre le style de combat à deux armes et le style de combat à distance. Ce choix détermine quelques aptitudes de classe, mais ne limite en rien le rôdeur pour le choix de ses dons ou de ses pouvoirs spéciaux.\r\nSi le rôdeur choisit le combat à deux armes, il peut se battre comme s’il possédait le don Combat à deux armes, même s’il n’en remplit pas les conditions.\r\nSi le rôdeur choisit le combat à distance, il peut se battre comme s’il possédait le don Tir rapide, même s’il n’en remplit pas les conditions.\r\nLe rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.\r\n	\r\n'));
SET @xc_cap_1245 := IFNULL(@xc_cap_1245, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Style de combat' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1245 := IFNULL(@xc_cap_1245, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Style de combat', cap_description = ' Au niveau 2, un rôdeur doit choisir entre le style de combat à deux armes et le style de combat à distance. Ce choix détermine quelques aptitudes de classe, mais ne limite en rien le rôdeur pour le choix de ses dons ou de ses pouvoirs spéciaux.\r\nSi le rôdeur choisit le combat à deux armes, il peut se battre comme s’il possédait le don Combat à deux armes, même s’il n’en remplit pas les conditions.\r\nSi le rôdeur choisit le combat à distance, il peut se battre comme s’il possédait le don Tir rapide, même s’il n’en remplit pas les conditions.\r\nLe rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.\r\n	\r\n', cap_type = '', cap_choix_mode = 'texte', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1245;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1256 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Endurance');
SET @xc_cap_1256 := IFNULL(@xc_cap_1256, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Endurance' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = 'Le personnage bénéficie d’un bonus de +4 sur chacun des tests et jets de sauvegarde suivants : les test de Natation joués pour résister à des dégâts temporaires, les tests de Constitution joués pour continuer à courir, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par une marche forcée, les tests de Constitution joués pour retenir sa respiration, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par la famine ou la soif, les jets de Vigueur joués pour éviter les dégâts non-létaux infligés par les climats chauds ou froids, ainsi que les jets de Vigueur joués pour résister aux dégâts infligés par l’asphyxie. De plus, le personnage peut dormir en armure légère ou intermédiaire sans se réveiller fatigué le lendemain.'));
SET @xc_cap_1256 := IFNULL(@xc_cap_1256, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Endurance' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1256 := IFNULL(@xc_cap_1256, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Endurance', cap_description = 'Le personnage bénéficie d’un bonus de +4 sur chacun des tests et jets de sauvegarde suivants : les test de Natation joués pour résister à des dégâts temporaires, les tests de Constitution joués pour continuer à courir, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par une marche forcée, les tests de Constitution joués pour retenir sa respiration, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par la famine ou la soif, les jets de Vigueur joués pour éviter les dégâts non-létaux infligés par les climats chauds ou froids, ainsi que les jets de Vigueur joués pour résister aux dégâts infligés par l’asphyxie. De plus, le personnage peut dormir en armure légère ou intermédiaire sans se réveiller fatigué le lendemain.', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1256;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1246 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Compagnon animal (rodeur)');
SET @xc_cap_1246 := IFNULL(@xc_cap_1246, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Compagnon animal (rodeur)' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = '<p>Un r&ocirc;deur peut avoir un compagnon animal choisi dans la liste suivante : aigle, blaireau, chameau, cheval (l&eacute;ger ou lourd), chien de selle, chien, chouette, faucon, loup, poney, rat sanguinaire et serpent venimeux (petit ou de taille moyenne). Si la campagne se d&eacute;roule enti&egrave;rement ou partiellement dans un milieu aquatique, on peut ajouter les animaux suivant &agrave; cette liste : calmar, marsouin et requin de taille moyenne. Un compagnon animal suit loyalement le personnage au cours de ses aventures au mieux de ses capacit&eacute;s. (Par exemple, une cr&eacute;ature aquatique ne peut suivre un r&ocirc;deur sur terre et ne peut &ecirc;tre choisi par un r&ocirc;deur n&rsquo;habitant pas un milieu aquatique qu&rsquo;avec des circonstances extraordinaire).</p>\n\n<p>En tous cas, le r&ocirc;le du compagnon animal est celui d&rsquo;une monture, d&rsquo;une sentinelle, d&rsquo;un &eacute;claireur ou d&rsquo;un animal de chasse, mais pas celui d&rsquo;un protecteur.</p>\n\n<p>Cet aptitude fonctionne exactement comme celle de druide du m&ecirc;me nom si ce n&rsquo;est que le niveau de druide effectif du personnage n&rsquo;est que la moiti&eacute; de son niveau de r&ocirc;deur.</p>\n\n<p>Un r&ocirc;deur peut choisir un compagnon animal hors- norme, au m&ecirc;me titre qu&rsquo;un druide, mais encore avec un niveau effectif divis&eacute; par deux. Comme pour un druide, un r&ocirc;deur ne peut choisir un compagnon animal qui r&eacute;duirait son niveau de druide effectif &agrave; 0 ou moins.</p>\n'));
SET @xc_cap_1246 := IFNULL(@xc_cap_1246, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Compagnon animal (rodeur)' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1246 := IFNULL(@xc_cap_1246, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Compagnon animal (rodeur)', cap_description = '<p>Un r&ocirc;deur peut avoir un compagnon animal choisi dans la liste suivante : aigle, blaireau, chameau, cheval (l&eacute;ger ou lourd), chien de selle, chien, chouette, faucon, loup, poney, rat sanguinaire et serpent venimeux (petit ou de taille moyenne). Si la campagne se d&eacute;roule enti&egrave;rement ou partiellement dans un milieu aquatique, on peut ajouter les animaux suivant &agrave; cette liste : calmar, marsouin et requin de taille moyenne. Un compagnon animal suit loyalement le personnage au cours de ses aventures au mieux de ses capacit&eacute;s. (Par exemple, une cr&eacute;ature aquatique ne peut suivre un r&ocirc;deur sur terre et ne peut &ecirc;tre choisi par un r&ocirc;deur n&rsquo;habitant pas un milieu aquatique qu&rsquo;avec des circonstances extraordinaire).</p>\n\n<p>En tous cas, le r&ocirc;le du compagnon animal est celui d&rsquo;une monture, d&rsquo;une sentinelle, d&rsquo;un &eacute;claireur ou d&rsquo;un animal de chasse, mais pas celui d&rsquo;un protecteur.</p>\n\n<p>Cet aptitude fonctionne exactement comme celle de druide du m&ecirc;me nom si ce n&rsquo;est que le niveau de druide effectif du personnage n&rsquo;est que la moiti&eacute; de son niveau de r&ocirc;deur.</p>\n\n<p>Un r&ocirc;deur peut choisir un compagnon animal hors- norme, au m&ecirc;me titre qu&rsquo;un druide, mais encore avec un niveau effectif divis&eacute; par deux. Comme pour un druide, un r&ocirc;deur ne peut choisir un compagnon animal qui r&eacute;duirait son niveau de druide effectif &agrave; 0 ou moins.</p>\n', cap_type = '', cap_choix_mode = 'texte', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1246;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1248 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Science du style de combat');
SET @xc_cap_1248 := IFNULL(@xc_cap_1248, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Science du style de combat' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = 'Au niveau 6, le rôdeur progresse dans son style de combat (à deux armes ou à distance). S’il a choisi le style de combat à deux armes au niveau 2, il peut maintenant se battre comme s’il possédait le don Science du combat à deux armes, même s’il n’en remplit pas les conditions.\r\nS’il a choisi le style de combat à distance au niveau 2, il peut maintenant se battre comme s’il possédait le don Feu nourri, même s’il n’en remplit pas les conditions.\r\nComme précédemment, le rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.'));
SET @xc_cap_1248 := IFNULL(@xc_cap_1248, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Science du style de combat' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0)));
SET @xc_cap_1248 := IFNULL(@xc_cap_1248, LAST_INSERT_ID());
UPDATE dd_capacites_speciales SET cap_nom = 'Science du style de combat', cap_description = 'Au niveau 6, le rôdeur progresse dans son style de combat (à deux armes ou à distance). S’il a choisi le style de combat à deux armes au niveau 2, il peut maintenant se battre comme s’il possédait le don Science du combat à deux armes, même s’il n’en remplit pas les conditions.\r\nS’il a choisi le style de combat à distance au niveau 2, il peut maintenant se battre comme s’il possédait le don Feu nourri, même s’il n’en remplit pas les conditions.\r\nComme précédemment, le rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1248;
SET @xc_ci := @xc_cla_126;
SET @xc_cap_1249 := (SELECT MIN(cap.cap_id) FROM dd_capacites_speciales cap JOIN dd_classe_capacite cc ON cc.cc_cap_id = cap.cap_id WHERE cc.cc_cla_id = @xc_cla_126 AND cap.cap_nom = 'Déplacement facilité');
SET @xc_cap_1249 := IFNULL(@xc_cap_1249, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Déplacement facilité' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = 'Un rôdeur de niveau 7 se déplace sans la moindre gêne dans toutes sortes de taillis, y compris les fourrés, les buissons (même épineux) et les autres zones de végétation dense. Il progresse normalement et ne subit aucun dégât. À noter toutefois que la végétation enchantée de manière à restreindre le mouvement continue de l’affecter.'));
