UPDATE dd_capacites_speciales SET cap_nom = 'Déplacement facilité', cap_description = 'Un rôdeur de niveau 7 se déplace sans la moindre gêne dans toutes sortes de taillis, y compris les fourrés, les buissons (même épineux) et les autres zones de végétation dense. Il progresse normalement et ne subit aucun dégât. À noter toutefois que la végétation enchantée de manière à restreindre le mouvement continue de l’affecter.', cap_type = '', cap_choix_mode = '', cap_choix_guerrier = 0, cap_classe_initiale = @xc_ci WHERE cap_id = @xc_cap_1249;
