SET @xc_cap_1251 := IFNULL(@xc_cap_1251, (SELECT MIN(cap_id) FROM dd_capacites_speciales WHERE cap_nom = 'Esquive totale' AND IFNULL(cap_classe_initiale, 0) = IFNULL(@xc_ci, 0) AND BINARY IFNULL(cap_description, '') = 'L’agilité presque surhumaine d’un rôdeur de niveau 9 lui permet d’éviter les attaques magiques ou inhabituelles. S’il réussit son jet de Réflexes contre une attaque dont les dégâts sont normalement réduits de moitié en cas de jet de Réflexes réussi (comme c’est le cas pour une boule de feu ou le souffle enflammé d’un dragon rouge), il l’évite totalement et ne subit pas le moindre dégât. Un rôdeur portant une armure intermédiaire ou lourde, ou qui se trouve sans défense (parce qu’il est inconscient ou paralysé, par exemple) perd les avantages de d’esquive totale.'));
