INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Empathie sauvage', '<p>Un r&ocirc;deur peut ajuster son comportement, son langage et ses expressions corporelles pour améliorer l\'attitude d\'un animal (comme un ours ou un varan). Cette aptitude suit les m&ecirc;mes règles que les tests de Diplomatie joués pour modifier l\'attitude d\'une personne. Le résultat d\'un test d\'empathie sauvage est déterminé par 1d20 + le niveau du r&ocirc;deur + le modificateur de Charisme du r&ocirc;deur. L\'attitude initiale des animaux domestiques est l\'indifférence, tandis que les animaux sauvages sont généralement inamicaux.</p>\n\n<p>Pour utiliser d\'empathie sauvage, le r&ocirc;deur et l\'animal doivent &ecirc;tre en mesure de se voir et de l\'étudier l\'un l\'autre, ce qui signifie qu\'ils doivent se trouver à moins de 9 mètres de distance dans des conditions normales. Il faut en moyenne une minute pour influencer un animal de cette fa&ccedil;on, mais comme pour la diplomatie, cela peut parfois prendre plus longtemps ou &ecirc;tre plus rapide.</p>\n\n<p>Cette aptitude peut aussi servir à un r&ocirc;deur pour influencer une créature magique dont la valeur d\'Intelligence est de 1 ou 2 (comme un basilic ou un girallon), avec cependant un malus de -4 sur son test.</p>\n', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1243 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Ennemis jurés', '<p>Au niveau 1, le r&ocirc;deur choisit un type de créatures de la Table : ennemis jurés du r&ocirc;deur. Pour avoir longuement étudié ses ennemis jurés et pour s\'&ecirc;tre exercé encore et encore aux techniques permettant de les vaincre, il bénéficie d\'un bonus de +2 aux tests de Bluff, Détection, Perception auditive, Psychologie et Survie lorsqu\'il les utilise contre des créatures de ce type. Il bénéficie également d\'un bonus de +2 sur les jets de dégêts d\'armes contre ces créatures.</p>\n\n<p>Au niveau 5 et tous les cinq niveaux par la suite (c\'est-à-dire aux niveaux 10, 15 et 20), le r&ocirc;deur peut choisir un nouvel ennemi juré sur la Table : ennemis jurés du r&ocirc;deur. De plus, il peut augmenter de +2 le bonus dont il bénéficie contre l\'un de ses ennemis jurés (y compris celui qu\'il vient de choisir s\'il le désire). Par exemple, un r&ocirc;deur de niveau 5 a deux ennemis jurés, un contre lequel il a un bonus de +4 sur les tests de Bluff, Détection, Perception auditive, Psychologie et Survie et les jets de dégêts d\'arme et un autre pour lequel le bonus n\'est que de +2. Au niveau 10, le m&ecirc;me r&ocirc;deur a trois ennemis jurés et il peut augmenter son bonus contre l\'un d\'eux de +2. Ses bonus seront alors soit de +4, +4 et +2, soit de +6, +2 et +2.</p>\n\n<p>Lorsqu\'un r&ocirc;deur choisit les Extérieurs ou les humano&iuml;des comme ennemi juré, il doit aussi choisir un sous-type associé, comme l\'indique la table. Si une créature appartient à deux sous-types d\'ennemi juré (par exemple, les démons sont à la fois du sous-type Chaos et Mal), les bonus ne se cumulent pas, le r&ocirc;deur ne profite que du plus élevé des deux. Voir livre de règles 1 pour plus de détails.</p>\n', '', 'texte', 0, @xc_ci FROM DUAL WHERE @xc_cap_1244 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Pistage', '<p>l faut r&eacute;ussir un test de Survie pour trouver des traces ou les suivre pendant 1,5 kilom&egrave;tre. Un nouveau test est n&eacute;cessaire lorsque la piste devient plus difficile &agrave; suivre, comme par exemple quand d\'autres traces la coupent ou quand elle se scinde en deux.</p>\n<p>Tant qu\'il piste, le personnage avance &agrave; la moiti&eacute; de sa vitesse de d&eacute;placement. Il peut avancer de sa vitesse de d&eacute;placement avec un malus aux tests de comp&eacute;tence de -5, ou au double de sa vitesse de d&eacute;placement avec un malus de -20 aux tests de comp&eacute;tence. Le DD d&eacute;pend du sol et des conditions en vigueur, selon la table suivante :</p>\n<p><code class=\"reg-tab-liste__tag\" title=\"Cliquer pour copier\">[[tab:pistage]]</code></p>\n<p><em>Sol tr&egrave;s mou</em>. Toute surface montrant des empreintes profondes et particuli&egrave;rement lisibles (neige, boue, &eacute;paisse couche de poussi&egrave;re, etc.).<br><em>Sol mou</em>. Toute surface assez &eacute;lastique pour s\'enfoncer sous le poids d\'un individu, mais plus r&eacute;sistante que la pr&eacute;c&eacute;dente. Les traces y sont nombreuses mais peu profondes.<br><em>Sol ferme</em>. La plupart des sols en ext&eacute;rieur (pelouse, champ, bois, etc.) et les surfaces molles ou extr&ecirc;mement sales &agrave; l\'int&eacute;rieur (&eacute;pais tapis, sol crasseux, etc.). La cr&eacute;ature suivie peut laisser quelques traces (brindilles cass&eacute;es, touffes de poils, etc.), mais les empreintes, elles, sont extr&ecirc;mement rares.<br><em>Sol dur</em>. Toute surface n\'imprimant pas la moindre empreinte (roche naturelle, plancher en pierre, etc.). La plupart des lits de cours d\'eau entrent dans cette cat&eacute;gorie, car les traces laiss&eacute;es sont g&eacute;n&eacute;ralement effac&eacute;es par le courant. La cr&eacute;ature suivie ne peut laisser que quelques indices de son passage (cailloux d&eacute;plac&eacute;s, marques de griffures, etc.).</p>\n<p>De nombreux modificateurs pouvant s\'appliquer au test de Survie sont pr&eacute;sentes ci-dessous :</p>\n<p>[[tab:classe-rodeur-pistage-modificateurs]]</p>\n<p><sup>1</sup> Si le groupe est compos&eacute; de cr&eacute;atures de tailles diverses, on prend seulement en compte la taille la plus importante.<br><sup>2</sup> Ces facteurs ne s\'additionnent pas ; seul le plus important est pris en compte.<br>Si le personnage rate son test de Survie, il peut r&eacute;essayer apr&egrave;s 1 heure (en ext&eacute;rieur) ou 10 minutes (&agrave; l\'int&eacute;rieur), moment qu\'il passe &agrave; essayer de retrouver la piste.</p>', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1255 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Voie du désert', '<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Les rodeurs b&eacute;douins d&eacute;veloppenent des capacit&eacute;s sp&eacute;ciales en relation avec le d&eacute;sert.&nbsp; Tous les pouvoirs des voies du d&eacute;sert sont extraordinaires (Ex).&nbsp;<br></span></p>\n<p><!-- [if !supportLists]--><!--[endif]-->Au niveau 1, le&nbsp;r&ocirc;deur b&eacute;douin choisit sa voie de d&eacute;part : <em>Le Chant des Puits</em> ou <em>La Voie du Rafiq</em>. Il ne peut puiser que dans celle-l&agrave;. Au niveau 9, il ouvre la seconde voie. D&egrave;s lors, il choisit librement dans les deux.</p>\n<p><span style=\"font-size: 10.5pt; font-family: \'Georgia\',serif; mso-fareast-font-family: Georgia; mso-bidi-font-family: Georgia; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Chaque capacit&eacute; sp&eacute;ciale indique un niveau de rodeur b&eacute;douin &agrave; partir duquel elle peut &ecirc;tre choisie.</span></p>', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1273 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Style de combat', ' Au niveau 2, un rôdeur doit choisir entre le style de combat à deux armes et le style de combat à distance. Ce choix détermine quelques aptitudes de classe, mais ne limite en rien le rôdeur pour le choix de ses dons ou de ses pouvoirs spéciaux.\r\nSi le rôdeur choisit le combat à deux armes, il peut se battre comme s’il possédait le don Combat à deux armes, même s’il n’en remplit pas les conditions.\r\nSi le rôdeur choisit le combat à distance, il peut se battre comme s’il possédait le don Tir rapide, même s’il n’en remplit pas les conditions.\r\nLe rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.\r\n	\r\n', '', 'texte', 0, @xc_ci FROM DUAL WHERE @xc_cap_1245 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Endurance', 'Le personnage bénéficie d’un bonus de +4 sur chacun des tests et jets de sauvegarde suivants : les test de Natation joués pour résister à des dégâts temporaires, les tests de Constitution joués pour continuer à courir, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par une marche forcée, les tests de Constitution joués pour retenir sa respiration, les tests de Constitution joués pour éviter les dégâts non-létaux infligés par la famine ou la soif, les jets de Vigueur joués pour éviter les dégâts non-létaux infligés par les climats chauds ou froids, ainsi que les jets de Vigueur joués pour résister aux dégâts infligés par l’asphyxie. De plus, le personnage peut dormir en armure légère ou intermédiaire sans se réveiller fatigué le lendemain.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1256 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Compagnon animal (rodeur)', '<p>Un r&ocirc;deur peut avoir un compagnon animal choisi dans la liste suivante : aigle, blaireau, chameau, cheval (l&eacute;ger ou lourd), chien de selle, chien, chouette, faucon, loup, poney, rat sanguinaire et serpent venimeux (petit ou de taille moyenne). Si la campagne se d&eacute;roule enti&egrave;rement ou partiellement dans un milieu aquatique, on peut ajouter les animaux suivant &agrave; cette liste : calmar, marsouin et requin de taille moyenne. Un compagnon animal suit loyalement le personnage au cours de ses aventures au mieux de ses capacit&eacute;s. (Par exemple, une cr&eacute;ature aquatique ne peut suivre un r&ocirc;deur sur terre et ne peut &ecirc;tre choisi par un r&ocirc;deur n&rsquo;habitant pas un milieu aquatique qu&rsquo;avec des circonstances extraordinaire).</p>\n\n<p>En tous cas, le r&ocirc;le du compagnon animal est celui d&rsquo;une monture, d&rsquo;une sentinelle, d&rsquo;un &eacute;claireur ou d&rsquo;un animal de chasse, mais pas celui d&rsquo;un protecteur.</p>\n\n<p>Cet aptitude fonctionne exactement comme celle de druide du m&ecirc;me nom si ce n&rsquo;est que le niveau de druide effectif du personnage n&rsquo;est que la moiti&eacute; de son niveau de r&ocirc;deur.</p>\n\n<p>Un r&ocirc;deur peut choisir un compagnon animal hors- norme, au m&ecirc;me titre qu&rsquo;un druide, mais encore avec un niveau effectif divis&eacute; par deux. Comme pour un druide, un r&ocirc;deur ne peut choisir un compagnon animal qui r&eacute;duirait son niveau de druide effectif &agrave; 0 ou moins.</p>\n', '', 'texte', 0, @xc_ci FROM DUAL WHERE @xc_cap_1246 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Science du style de combat', 'Au niveau 6, le rôdeur progresse dans son style de combat (à deux armes ou à distance). S’il a choisi le style de combat à deux armes au niveau 2, il peut maintenant se battre comme s’il possédait le don Science du combat à deux armes, même s’il n’en remplit pas les conditions.\r\nS’il a choisi le style de combat à distance au niveau 2, il peut maintenant se battre comme s’il possédait le don Feu nourri, même s’il n’en remplit pas les conditions.\r\nComme précédemment, le rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1248 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Déplacement facilité', 'Un rôdeur de niveau 7 se déplace sans la moindre gêne dans toutes sortes de taillis, y compris les fourrés, les buissons (même épineux) et les autres zones de végétation dense. Il progresse normalement et ne subit aucun dégât. À noter toutefois que la végétation enchantée de manière à restreindre le mouvement continue de l’affecter.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1249 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Pistage accéléré', 'Un rôdeur de niveau 8 peut se déplacer à sa vitesse habituelle lorsqu’il suit une piste, sans subir le malus de –5 sur ses tests de Survie. Il ne subit qu’un malus de –10 (au lieu de –20) sur ses tests de Survie lorsqu’il se déplace au double de sa vitesse lorsqu’il suit une piste.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1250 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Esquive totale', 'L’agilité presque surhumaine d’un rôdeur de niveau 9 lui permet d’éviter les attaques magiques ou inhabituelles. S’il réussit son jet de Réflexes contre une attaque dont les dégâts sont normalement réduits de moitié en cas de jet de Réflexes réussi (comme c’est le cas pour une boule de feu ou le souffle enflammé d’un dragon rouge), il l’évite totalement et ne subit pas le moindre dégât. Un rôdeur portant une armure intermédiaire ou lourde, ou qui se trouve sans défense (parce qu’il est inconscient ou paralysé, par exemple) perd les avantages de d’esquive totale.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1251 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Maîtrise du style de combat', 'Au niveau 11, le rôdeur maîtrise totalement son style de combat (à deux armes ou à distance). S’il a choisi le style de combat à deux armes au niveau 2, il peut maintenant se battre comme s’il possédait le don Maîtrise du combat à deux armes, même s’il n’en remplit pas les conditions.\r\nS’il a choisi le style de combat à distance au niveau 2, il peut maintenant se battre comme s’il possédait le don Science du tir de précision, même s’il n’en remplit pas les conditions.\r\nComme précédemment, le rôdeur ne doit porter aucune armure ou seulement une armure légère pour bénéficier de son style de combat. Il en perd tous les avantages s’il porte une arme intermédiaire ou lourde.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1252 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Camouflage', 'Un rôdeur de niveau 13 ou plus peut utiliser la compétence Discrétion même s’il ne bénéficie pas d’un abri ou de camouflage, à condition de se trouver sur un terrain de type naturel.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1253 IS NULL;
INSERT INTO dd_capacites_speciales (cap_nom, cap_description, cap_type, cap_choix_mode, cap_choix_guerrier, cap_classe_initiale) SELECT 'Discrétion totale', 'Un rôdeur de niveau 17 ou plus se trouvant sur un terrain de type naturel peut utiliser la compétence Discrétion même s’il est actuellement observé.', '', '', 0, @xc_ci FROM DUAL WHERE @xc_cap_1254 IS NULL;
